  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 9, $j$3.1 Minerals$j$, $j${"readings": [{"title": "Job 28 (King James Version)", "url": "/portal/bible/Job/28"}], "body": "Rocks are made of minerals, and minerals are the building blocks of the solid Earth. Job 28:1 says, Surely there is a vein for the silver, and a place for gold where they fine it. Job 28:2 adds, Iron is taken out of the earth, and brass is molten out of the stone. People have mined the earth's riches since ancient times.\n\nA mineral is a natural, solid, inorganic substance with a definite chemical composition and an orderly crystal structure. Natural means it forms in nature and not in a factory. Inorganic means it was never alive. The atoms of a mineral are arranged in a repeating pattern, which gives the crystal its shape. Quartz, with the formula SiO2, and halite, which is table salt, NaCl, are common examples. More than 5000 minerals are known, but only a few dozen are common. The most abundant elements in the crust are oxygen and silicon, so silicate minerals are the largest group.\n\nMinerals form when magma cools, when water evaporates and leaves dissolved minerals behind, and when heat and pressure change existing minerals. Slowly cooling magma lets large crystals grow. Fast cooling makes small crystals.\n\nGeologists identify minerals by their properties. Color can vary and is not always reliable. Streak is the color of the powder left when a mineral is scraped on a white tile. Luster describes how it shines, such as metallic or glassy. Hardness is how easily it scratches. The Mohs scale ranks ten minerals from 1 to 10: talc, gypsum, calcite, fluorite, apatite, orthoclase, quartz, topaz, corundum and diamond. A fingernail has a hardness of about 2.5, a copper penny about 3, and a steel nail about 5.5. Cleavage is a mineral's tendency to split along flat surfaces, and fracture describes an uneven break. Density, magnetism, and a reaction to acid are also helpful. Calcite fizzes in a drop of weak acid.\n\nAn ore is a rock that contains enough of a valuable mineral to be mined at a profit. Hematite is an ore of iron, bauxite of aluminum and galena of lead. Gems such as emeralds and diamonds are valued for beauty and rarity. Minerals are used in buildings, phones, cars and medicine. Mining brings jobs and also environmental costs, so wise stewardship asks miners to restore the land afterward.\n\nYour task: (1) List the five parts of the definition of a mineral. (2) Describe three ways to identify a mineral. (3) Tell what an ore is and give two examples.\n\nFlorida standards: SC.912.E.6.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SC.912.E.6", "script": "Welcome back. Listen, Job 28:1 says, Surely there is a vein for the silver, and a place for gold where they fine it. People have mined the earth's riches since ancient times.\n\nNow watch this. A mineral is natural, solid, inorganic, has a definite chemical composition and has an orderly crystal structure. Quartz and halite are examples. Oxygen and silicon are the most abundant elements in the crust, so silicates are the biggest group. Slow cooling makes large crystals. Fast cooling makes small ones.\n\nLook at identification. Streak is the color of the powder. Luster is how it shines. Hardness is how easily it scratches, measured on the Mohs scale from talc at 1 to diamond at 10. A fingernail is about 2.5. A steel nail is about 5.5. Cleavage is splitting along flat surfaces. Calcite fizzes in weak acid.\n\nAn ore is a rock with enough of a valuable mineral to mine at a profit. Hematite is an ore of iron. Bauxite is an ore of aluminum. Mining has costs, so good stewardship restores the land afterward.\n\nYour task is to define a mineral, describe ways to identify one and explain what an ore is. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$3.1 Minerals$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 10, $j$3.2 Rocks and the Rock Cycle$j$, $j${"readings": [{"title": "Isaiah 51 (King James Version)", "url": "/portal/bible/Isaiah/51"}], "body": "A rock is a solid mixture of one or more minerals or other materials. Isaiah 51:1 says, Look unto the rock whence ye are hewn, and to the hole of the pit whence ye are digged. Rocks tell the story of how our planet was formed and changed. Geologists sort rocks into three groups by the way they form.\n\nIgneous rocks form when magma or lava cools and hardens. Intrusive igneous rocks cool slowly underground and have large crystals. Granite, a light colored rock, is an example. Extrusive igneous rocks cool quickly on the surface and have small crystals or none. Basalt, a dark rock that forms most of the ocean floor, is extrusive. Obsidian is a volcanic glass that cooled so quickly it formed no crystals.\n\nSedimentary rocks form from layers of sediment, which are pieces of rock, shell and plant material. Sediment is deposited in layers, usually in water. Layers on the bottom are squeezed by the weight above in a process called compaction, and dissolved minerals glue the grains together in cementation. Together they are called lithification. Clastic sedimentary rocks are made of rock fragments. Sandstone is made of sand, shale of clay and conglomerate of rounded pebbles. Chemical sedimentary rocks, such as rock salt, form when water evaporates. Organic sedimentary rocks, such as coal and some limestone, come from plants or shells. Sedimentary rocks often show layers and may contain fossils. Most of Florida's bedrock is limestone.\n\nMetamorphic rocks form when heat and pressure change existing rock without melting it completely. Limestone becomes marble. Shale becomes slate, and then schist. Sandstone becomes quartzite. Granite becomes gneiss, which shows bands. Foliated metamorphic rocks have layers or bands, and nonfoliated ones, such as marble, do not.\n\nThe rock cycle shows that rocks change from one type to another over time. Any rock can be weathered into sediment, which can become sedimentary rock. Any rock can be buried and changed into metamorphic rock. Any rock can melt and cool as igneous rock. Heat from inside the Earth, plate movement, and weathering at the surface keep the cycle going. Nothing in the cycle is lost. It is recycled.\n\nYour task: (1) Describe how each of the three rock groups forms. (2) Give two examples of each group. (3) Trace one path through the rock cycle.\n\nFlorida standards: SC.912.E.6.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SC.912.E.6", "script": "Welcome back. Listen, Isaiah 51:1 says, Look unto the rock whence ye are hewn. Rocks tell the story of how our planet was formed and changed.\n\nNow watch this. There are three groups. Igneous rocks form when magma or lava cools. Slow cooling underground makes large crystals, like granite. Fast cooling on the surface makes small crystals, like basalt. Obsidian is volcanic glass.\n\nSedimentary rocks form from layers of sediment. Compaction squeezes the layers. Cementation glues the grains together. Sandstone, shale and conglomerate are made of fragments. Rock salt forms by evaporation. Coal and some limestone come from living things. Most of Florida's bedrock is limestone. Look for layers and fossils.\n\nMetamorphic rocks form when heat and pressure change existing rock without fully melting it. Limestone becomes marble. Shale becomes slate. Granite becomes gneiss.\n\nThe rock cycle shows any rock can become any other. Weathering makes sediment, burial and pressure make metamorphic rock, and melting and cooling make igneous rock. Nothing is lost. It is recycled.\n\nYour task is to describe the three rock groups, give examples and trace a path through the cycle. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$3.2 Rocks and the Rock Cycle$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 11, $j$3.3 Weathering, Erosion and Soil$j$, $j${"readings": [{"title": "Matthew 7 (King James Version)", "url": "/portal/bible/Matthew/7"}], "body": "Rock at Earth's surface slowly breaks down. In Matthew 7:24 to 27, Jesus told of a wise man who built his house upon a rock, and a foolish man who built his house upon the sand. Ground and what lies under it matter for every building and every farm.\n\nWeathering is the breaking down of rock into smaller pieces. Mechanical weathering breaks rock without changing its chemistry. In frost wedging, water seeps into cracks, freezes and expands, and splits the rock. Roots can pry rock apart. Abrasion happens when rock surfaces are scraped by wind and water carrying sand. Chemical weathering changes the minerals. Rain mixes with carbon dioxide to make a weak carbonic acid that slowly dissolves limestone, and oxygen causes oxidation, which rusts iron minerals red. Warm, wet climates weather rock faster, and Florida's warm rain dissolves its limestone steadily.\n\nErosion is the movement of weathered material by wind, water, ice and gravity. Deposition is the dropping of the material in a new place. Landslides and mudslides are gravity at work, and rivers carry the most sediment of all.\n\nSoil is a mixture of weathered rock, minerals, organic matter, water and air. Humus is the dark organic matter from decayed plants and animals, which makes soil fertile. Soil takes hundreds of years to form even a few centimeters. A soil profile has layers called horizons. The O horizon is the organic surface layer. The A horizon, or topsoil, is rich in humus and best for plants. The B horizon, the subsoil, has clay and minerals washed down from above. The C horizon is partly weathered rock above the bedrock. Florida soils are often sandy and low in nutrients, so Florida growers add fertilizer and organic matter.\n\nCareless farming can destroy soil. In the 1930s dry winds blew away the topsoil of the Great Plains in the Dust Bowl, after the prairie grass was plowed up and drought struck. Today farmers protect soil with contour plowing, terraces, cover crops and windbreaks. Genesis 2:15 says the LORD God took the man, and put him into the garden of Eden to dress it and to keep it. Keeping the soil is part of keeping the garden.\n\nYour task: (1) Compare mechanical and chemical weathering. (2) Name the soil horizons in order. (3) Describe two ways to prevent soil erosion.\n\nFlorida standards: SC.912.E.6.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SC.912.E.6", "script": "Welcome back. Listen, Matthew 7:24 tells of a wise man who built his house upon a rock. The ground and what lies under it matter for every building and every farm.\n\nNow watch this. Weathering breaks down rock. Mechanical weathering breaks it without changing its chemistry. Frost wedging splits rock when water freezes in cracks. Roots and abrasion break rock too. Chemical weathering changes the minerals. Rain with carbon dioxide makes a weak acid that dissolves limestone. Oxygen rusts iron minerals. Warm, wet climates weather rock faster.\n\nErosion moves the pieces by wind, water, ice and gravity. Deposition drops them in a new place.\n\nSoil is weathered rock mixed with humus, water and air. Look at the horizons. O is the organic layer. A is the topsoil. B is the subsoil. C is partly weathered rock above the bedrock. Florida soils are often sandy and low in nutrients.\n\nIn the 1930s the Dust Bowl blew away topsoil. Today farmers use contour plowing, terraces and cover crops. Genesis 2:15 says to dress the garden and to keep it.\n\nYour task is to compare kinds of weathering, name the horizons and describe how to prevent erosion. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$3.3 Weathering, Erosion and Soil$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 12, $j$3.4 Rivers, Groundwater, Glaciers, Wind and Waves$j$, $j${"readings": [{"title": "Job 14 (King James Version)", "url": "/portal/bible/Job/14"}], "body": "Moving water, ice and wind shape the land. Job 14:19 says, The waters wear the stones. Over long times, these forces carve valleys, build beaches and move mountains of material.\n\nRunning water is the most important agent of erosion. A stream erodes steep land and makes a V shaped valley. Where the land flattens, the river slows, bends in curves called meanders and drops sediment. A floodplain is the flat land beside a river that floods. When a river enters the ocean, it slows and drops its sediment in a fan shaped delta, as the Mississippi River has done. Floods are natural, and people who build on floodplains need good planning.\n\nGroundwater is water that soaks into the ground and fills the spaces in soil and rock. The top of the saturated zone is the water table. An aquifer is rock or sediment that holds and moves usable water. Groundwater dissolves limestone and makes caves. When the roof of an underground cave or void collapses, a sinkhole forms. Sinkholes are common in Florida.\n\nA glacier is a large mass of moving ice. Valley glaciers flow down mountains, and continental glaciers cover large areas such as Greenland and Antarctica. Glaciers carve U shaped valleys, scrape bedrock and carry boulders far from where they started. Material left by a glacier is called till. The Great Lakes were scoured by ice during the last ice age.\n\nWind erodes by deflation, which lifts loose particles, and by abrasion, which sandblasts rock. Wind carries sand and builds dunes. It also carries fine dust that can settle into a deposit called loess. Wind erosion is greatest in dry places with little plant cover.\n\nOcean waves erode coastlines and build beaches. Waves that strike the shore at an angle move sand along the coast in a process called longshore drift. Barrier islands and beaches are made of moving sand, and Florida's coast is lined with them. Storms and rising seas can wash sand away, so Broward County and many cities add sand in beach renourishment projects. Sea walls, dunes with sea oats and protected dunes help hold sand.\n\nYour task: (1) Describe a river valley, a meander and a delta. (2) Explain how a sinkhole forms. (3) Tell how waves can build and erode a beach.\n\nFlorida standards: SC.912.E.6.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SC.912.E.6", "script": "Welcome back. Listen, Job 14:19 says, The waters wear the stones. Over long times, water, ice and wind carve valleys, build beaches and move mountains of material.\n\nNow watch this. Running water is the main agent of erosion. In steep land a stream cuts a V shaped valley. In flat land the river slows, makes curves called meanders and drops sediment. Where a river meets the ocean it drops sediment in a delta. A floodplain is the flat land that floods.\n\nGroundwater fills spaces in soil and rock below the water table. An aquifer holds usable water. Groundwater dissolves limestone and can make caves. When the roof of a cave collapses, a sinkhole forms. Sinkholes are common in Florida.\n\nGlaciers are moving ice. They carve U shaped valleys and leave piles of till. Wind erodes by deflation and abrasion, builds dunes and deposits loess.\n\nWaves erode coasts and build beaches. Longshore drift moves sand along the shore. Florida adds sand in beach renourishment, and dunes with sea oats help hold sand in place.\n\nYour task is to describe river features, explain a sinkhole and tell how waves shape a beach. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$3.4 Rivers, Groundwater, Glaciers, Wind and Waves$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 3, $j$Assessment 3: Minerals, Rocks and Earth's Surface$j$, $j${"prompt": "Write a report of at least 250 words on minerals, rocks and the surface of the earth. Use complete sentences and label each part. Isaiah 51:1 says, Look unto the rock whence ye are hewn, and to the hole of the pit whence ye are digged.\n\nPart 1: Define a mineral. Describe how to identify a mineral using streak, luster, hardness, cleavage and one other property, and explain what an ore is.\nPart 2: Describe how igneous, sedimentary and metamorphic rocks form, and give two examples of each. Explain why granite and basalt have different crystal sizes.\nPart 3: Trace a path through the rock cycle for a piece of granite that becomes sandstone and then quartzite. Name the processes at each step.\nPart 4: Compare mechanical and chemical weathering with two examples each. Name the soil horizons, explain why soil is valuable, and describe two ways to prevent erosion.\nPart 5: Describe how a river, groundwater, a glacier, wind and waves each shape the land, and explain how Florida's limestone and sandy coast are affected. Explain how Genesis 2:15 guides the care of soil and land.", "rubric": "100 points. Part 1: 20 points. Part 2: 20 points. Part 3: 15 points. Part 4: 20 points. Part 5: 20 points. Complete sentences and conventions: 5 points. A score of 70 or above is passing."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Assessment 3: Minerals, Rocks and Earth's Surface$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'discussion', 3, $j$Discussion 3: Built on the Rock$j$, $j${"prompt": "Write a post of at least 120 words that (1) describes a rock, mineral, beach or soil you have seen and what you noticed about it, (2) explains in your own words how one rock type changes into another over time, (3) explains how Jesus' parable of the house on the rock in Matthew 7:24 to 27 can picture a life built on solid ground, and (4) connects your answer to Isaiah 51:1, Matthew 7:24 or Genesis 2:15. Then write a respectful reply of at least 40 words to another student's post, or answer this question: How can believers care for the soil and the land God has given us? Keep your tone kind and respectful of other views."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'discussion' and title = $j$Discussion 3: Built on the Rock$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 11, $j$Check 3.1: Minerals$j$, $j${"questions": [{"q": "Which is NOT required for a substance to be a mineral?", "options": ["It must form naturally", "It must be a liquid", "It must be a solid", "It must have a definite chemical composition"]}, {"q": "The color of a mineral's powder when it is scraped on a white tile is its:", "options": ["Streak", "Cleavage", "Fracture", "Luster"]}, {"q": "On the Mohs scale, the hardest mineral is:", "options": ["Diamond", "Talc", "Calcite", "Quartz"]}, {"q": "A rock that contains enough of a valuable mineral to be mined at a profit is an:", "options": ["Ore", "Crystal", "Gem", "Fossil"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.1: Minerals$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,0,0,0}'::int[], array[$j$Minerals are solids.$j$,$j$Streak is more reliable than surface color.$j$,$j$Diamond is 10 and talc is 1.$j$,$j$Hematite is an ore of iron.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.1: Minerals$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 12, $j$Check 3.2: Rocks and the Rock Cycle$j$, $j${"questions": [{"q": "Rocks that form when magma cools and hardens are:", "options": ["Sedimentary rocks", "Fossils", "Igneous rocks", "Metamorphic rocks"]}, {"q": "Limestone that is changed by heat and pressure becomes:", "options": ["Marble", "Basalt", "Slate", "Granite"]}, {"q": "Which process glues sediment grains together to form sedimentary rock?", "options": ["Erosion", "Foliation", "Melting", "Cementation"]}, {"q": "Granite has large crystals because it:", "options": ["Cooled quickly on the surface", "Formed from shells", "Formed from sand", "Cooled slowly underground"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.2: Rocks and the Rock Cycle$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,0,3,3}'::int[], array[$j$Igneous means formed from fire or melt.$j$,$j$Marble is metamorphosed limestone.$j$,$j$Dissolved minerals fill spaces and bind the grains.$j$,$j$Slow cooling allows crystals to grow.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.2: Rocks and the Rock Cycle$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 13, $j$Check 3.3: Weathering, Erosion and Soil$j$, $j${"questions": [{"q": "Water freezing in a crack and splitting a rock is an example of:", "options": ["Oxidation", "Cementation", "Frost wedging", "Deposition"]}, {"q": "The movement of weathered material from one place to another is called:", "options": ["Weathering", "Compaction", "Cementation", "Erosion"]}, {"q": "The soil layer richest in humus, best for plants, is the:", "options": ["C horizon", "A horizon", "Bedrock", "B horizon"]}, {"q": "Which is a way to reduce soil erosion on a slope?", "options": ["Plowing straight downhill", "Terracing", "Removing all plants", "Leaving soil bare"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.3: Weathering, Erosion and Soil$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,3,1,1}'::int[], array[$j$Ice expands as it freezes.$j$,$j$Wind, water, ice and gravity cause erosion.$j$,$j$Topsoil is the A horizon.$j$,$j$Terraces slow the flow of water down a slope.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.3: Weathering, Erosion and Soil$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 14, $j$Check 3.4: Rivers, Groundwater, Glaciers, Wind and Waves$j$, $j${"questions": [{"q": "A fan shaped deposit of sediment where a river enters the ocean is a:", "options": ["Moraine", "Dune", "Meander", "Delta"]}, {"q": "The top of the saturated zone underground is the:", "options": ["Floodplain", "Aquifer roof", "Water table", "Horizon"]}, {"q": "Glaciers typically carve valleys that are shaped like the letter:", "options": ["U", "V", "S", "Z"]}, {"q": "The movement of sand along a coast by waves hitting the shore at an angle is:", "options": ["Longshore drift", "Subduction", "Deflation", "Cementation"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.4: Rivers, Groundwater, Glaciers, Wind and Waves$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{3,2,0,0}'::int[], array[$j$The river slows and drops its sediment.$j$,$j$Below the water table the ground is full of water.$j$,$j$Rivers cut V shapes, and glaciers cut U shapes.$j$,$j$Waves push sand along the beach.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.4: Rivers, Groundwater, Glaciers, Wind and Waves$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 15, $j$Unit Quiz 3: Minerals, Rocks and Earth's Surface$j$, $j${"questions": [{"q": "Quartz is a mineral with a hardness of:", "options": ["10 on the Mohs scale", "3 on the Mohs scale", "7 on the Mohs scale", "1 on the Mohs scale"]}, {"q": "A mineral that splits along flat surfaces shows:", "options": ["Density", "Luster", "Cleavage", "Streak"]}, {"q": "Which is an extrusive igneous rock?", "options": ["Marble", "Sandstone", "Granite", "Basalt"]}, {"q": "Which is a clastic sedimentary rock?", "options": ["Sandstone", "Slate", "Obsidian", "Gneiss"]}, {"q": "A rock with bands or layers formed by heat and pressure is called:", "options": ["Volcanic glass", "Foliated metamorphic rock", "Intrusive igneous rock", "Organic sedimentary rock"]}, {"q": "Rain with dissolved carbon dioxide dissolves limestone through:", "options": ["Chemical weathering", "Abrasion", "Deposition", "Frost wedging"]}, {"q": "The Dust Bowl of the 1930s was caused by drought and:", "options": ["Plowing up grasslands that held the soil", "Glaciers", "Too many forests", "Volcanic eruptions"]}, {"q": "An underground cave roof that collapses can form a:", "options": ["Sinkhole", "Moraine", "Delta", "Dune"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 3: Minerals, Rocks and Earth's Surface$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,2,3,0,1,0,0,0}'::int[], array[$j$Quartz is 7 and can scratch glass.$j$,$j$Cleavage is splitting along flat planes.$j$,$j$Basalt cools quickly on the surface.$j$,$j$It is made of cemented grains of sand.$j$,$j$Gneiss is a banded metamorphic rock.$j$,$j$Carbonic acid reacts with calcite.$j$,$j$Bare soil blew away in the wind.$j$,$j$Sinkholes are common where limestone dissolves.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 3: Minerals, Rocks and Earth's Surface$j$ on conflict (item_id) do nothing;
